mapper.select:
		SELECT
			IFNULL(IFNULL(te.INSTRUCTION_ID, teh.INSTRUCTION_ID), IFNULL(tie.INSTRUCTION_ID, tieh.INSTRUCTION_ID)) ORDER_ID,
			case when ptl.PROFIT_TYPE = '01' then 'FVTPL' else 'AC' end as invAim,ee.ENTRUST_ID,


			LEFT JOIN T_ENTRUSTHISTORY teh ON TRIM(LEADING substr(std.APPLY_TRADE_ID, 6, length(std.APPLY_TRADE_ID)) from '0') = teh.BROKER_ENTRUST_ID
				and teh.ENTRUST_STATUS IN ('2', '5', '6', '8') AND DATE_FORMAT(DEAL_DATE, '%Y%m%d') = teh.TRADING_DAY AND (std.TRADE_PLAT = '02' or std.TRADE_PLAT IS NULL)
			LEFT JOIN T_ENTRUST te ON TRIM(LEADING substr(std.APPLY_TRADE_ID, 6, length(std.APPLY_TRADE_ID)) from '0') = te.BROKER_ENTRUST_ID
				and te.ENTRUST_STATUS IN ('2', '5', '6', '8') AND DATE_FORMAT(DEAL_DATE, '%Y%m%d') = te.TRADING_DAY AND (std.TRADE_PLAT = '02' or std.TRADE_PLAT IS NULL)
			LEFT JOIN T_INTEGRATED_ENTRUSTHISTORY tieh ON TRIM(LEADING substr(std.APPLY_TRADE_ID, 6, length(std.APPLY_TRADE_ID)) from '0') = tieh.BROKER_ENTRUST_ID
				and tieh.ENTRUST_STATUS IN ('2', '5', '6', '8') AND DATE_FORMAT(DEAL_DATE, '%Y%m%d') = tieh.TRADING_DAY AND std.TRADE_PLAT IN ('03', '04', '05')
			LEFT JOIN T_INTEGRATED_ENTRUST tie ON TRIM(LEADING substr(std.APPLY_TRADE_ID, 6, length(std.APPLY_TRADE_ID)) from '0') = tie.BROKER_ENTRUST_ID
				and tie.ENTRUST_STATUS IN ('2', '5', '6', '8') AND DATE_FORMAT(DEAL_DATE, '%Y%m%d') = tie.TRADING_DAY AND std.TRADE_PLAT IN ('03', '04', '05')
			LEFT JOIN ETR_ENTRUST ee ON (ee.ENTRUST_ID = IFNULL(te.INSTRUCTION_ID, teh.INSTRUCTION_ID) OR ee.ENTRUST_ID = IFNULL(tie.INSTRUCTION_ID, tieh.INSTRUCTION_ID))
			LEFT JOIN PTL_PORTFOLIO ptl ON (ptl.PORTFOLIO_ID = std.PORTFOLIO_ID)



				std.DEAL_DATE = #{dealDate,jdbcType=DATE}



           			#{finprodId,jdbcType=VARCHAR}



				AND std.BUSI_TYPE = #{busiType,jdbcType=VARCHAR}



           			#{busiType,jdbcType=VARCHAR}




           			#{portfolioId,jdbcType=VARCHAR}




					#{ps,jdbcType=VARCHAR}

SELECT
IFNULL(te.INSTRUCTION_ID, teh.INSTRUCTION_ID) ORDER_ID,
ee.INV_AIM invAim,


--INNER JOIN SETTLE_TRANS_DATA_ADD stda ON stda.TRADE_ID=std.TRADE_ID
LEFT JOIN T_ENTRUSTHISTORY teh ON std.APPLY_TRADE_ID = teh.ENTRUST_ID
LEFT JOIN T_ENTRUST te ON std.APPLY_TRADE_ID = te.ID
LEFT JOIN ETR_ENTRUST ee ON ee.ENTRUST_ID = IFNULL(te.INSTRUCTION_ID, teh.INSTRUCTION_ID)

	(te.ID IS NOT NULL OR teh.ENTRUST_ID IS NOT NULL)

		AND std.DEAL_DATE = #{dealDate,jdbcType=DATE}


		AND std.BUSI_TYPE = #{busiType,jdbcType=VARCHAR}



			#{portfolioId,jdbcType=VARCHAR}




			#{ps,jdbcType=VARCHAR}
